interface VariantSectionProps extends DefaultVariantSectionProps {
  menu?: () => React.ReactElement;
  onAddNewVariant?: () => void;
  isDraggable?: boolean;
  isDragging?: boolean;
  dragHandleProps?: DraggableProvidedDragHandleProps;
  emptyAddButtonTooltip?: React.ReactNode;
  onClickSettings?: () => void;
  exprButton?: PlasmicVariantSection__OverridesType["exprButton"];
}

const VariantSection = function VariantSection(
  props: VariantSectionProps,
) {
  const {
    menu,
    onAddNewVariant,
    dragHandleProps,
    isDraggable,
    isDragging: _isDragging,
    emptyAddButtonTooltip,
    onClickSettings,
    ...rest
  } = props;

  const contextMenuProps = useContextMenu({ menu });
  const isEmpty = React.Children.count(props.children) === 0;

  const [hover, setHover] = React.useState(false);
  return (
    <PlasmicVariantSection
      header={{
        props: {
          ...contextMenuProps,
          onMouseEnter: () => setHover(true),
          onMouseLeave: () => setHover(false),
        },
      }}
      emptyAddButton={
        onAddNewVariant
          ? {
              onClick: onAddNewVariant,
              tooltip: emptyAddButtonTooltip ?? props.emptyAddButtonText,
              "data-test-class": "add-variant-button",
              "data-event": "variantspanel-section-add-variant-to-group",
            }
          : { render: () => null }
      }
      addButton={
        onAddNewVariant
          ? {
              onClick: onAddNewVariant,
              tooltip: isEmpty
                ? (emptyAddButtonTooltip ?? props.emptyAddButtonText)
                : props.emptyAddButtonText,
              "data-test-class": "add-variant-button",
              "data-event": "variantspanel-section-add-variant-to-group",
            }
          : { render: () => null }
      }
      showSettings={!!onClickSettings}
      settingsButton={{ onClick: onClickSettings }}
      menuButton={menu ? { props: { ...contextMenuProps } } : undefined}
      state={isEmpty ? "empty" : undefined}
      dragHandle={{
        style: {
          display: isDraggable ? (hover ? "flex" : "none") : "none",
        },

        ...dragHandleProps,
      }}
      root={
        {
          "data-test-class": "variants-section",
        } as any
      }
      {...rest}
    />
  );
};

export default VariantSection;

export interface ReadOnlyVariantInputs {
  readonly canChangeVariants: boolean;
  readonly variants: readonly { readonly variant: Variant; readonly pinState: VariantPinState | undefined; readonly canTarget: boolean; readonly canToggle: boolean }[];
}

export function makeReadOnlySection(opts: {
  studioCtx: StudioCtx;
  viewCtx?: ViewCtx;
  vcontroller: VariantsController;
  icon: React.ReactNode;
  title: React.ReactNode;
  onClickSettings?: () => void;
  variants: Variant[];
  key: string;
  showIcon?: boolean;
  component?: Component;
  readInputs?: ReadOnlyVariantInputs;
}) {
  const {
    variants,
    studioCtx,
    viewCtx,
    vcontroller,
    title,
    icon,
    onClickSettings,
    key,
    showIcon,
    component,
  } = opts;
  const readInputs = opts.readInputs;
  const canChangeVariants = readInputs ? readInputs.canChangeVariants : vcontroller.canChangeActiveVariants();
  return (
    <VariantSection
      key={key}
      icon={icon}
      title={title}
      showIcon={showIcon}
      onClickSettings={onClickSettings}
    >
      {variants.map((variant) => {
        const read = readInputs ? ensure(readInputs.variants.find((input) => input.variant === variant), "Native variant row input must match its command handle") : undefined;
        return <VariantRow
          key={variant.uuid}
          variant={variant}
          studioCtx={studioCtx}
          viewCtx={viewCtx}
          pinState={read ? read.pinState : vcontroller.getPinState(variant)}
          menu={
            component
              ? makeVariantMenu({
                  variant,
                  component,
                  onCopyTo: (toVariant) =>
                    spawn(
                      studioCtx.change(() => {
                        studioCtx
                          .tplMgr()
                          .copyToVariant(component, variant, toVariant);
                        return ok();
                      }),
                    ),
                })
              : undefined
          }
          onClick={() =>
            studioCtx.changeUnsafe(() => vcontroller.onClickVariant(variant))
          }
          onTarget={
            (read ? read.canTarget : canChangeVariants || vcontroller.canToggleTargeting(variant))
              ? (target) =>
                  studioCtx.changeUnsafe(() =>
                    vcontroller.onTargetVariant(variant, target),
                  )
              : undefined
          }
          onToggle={
            (read ? read.canToggle : canChangeVariants)
              ? () =>
                  studioCtx.changeUnsafe(() =>
                    vcontroller.onToggleVariant(variant),
                  )
              : undefined
          }
          label={() =>
            isStyleOrCodeComponentVariant(variant) ? (
              <SelectorTags
                isCodeComponent={isTplCodeComponent(component?.tplTree)}
                selectors={styleOrCodeComponentVariantToSelectors(
                  variant,
                  studioCtx.site,
                )}
              />
            ) : (
              variant.name
            )
          }
          isReadOnly
        />
      })}
    </VariantSection>
  );
}
